FROM ((Bottle INNER JOIN ((Bottle_Q INNER JOIN (Cast INNER JOIN Prodo_Bottle ON Cast.Cst_Cnt = Prodo_Bottle.Cst_Cnt) ON Bottle_Q.Btl_Cnt = Prodo_Bottle.Btl_Cnt) INNER JOIN Rpt_Data ON Prodo_Bottle.Btl_Cnt = Rpt_Data.Btl_Cnt) ON Bottle.Btl_Cnt = Bottle_Q.Btl_Cnt) INNER JOIN Chl ON Bottle.Btl_Cnt = Chl.Btl_Cnt) INNER JOIN Nuts ON (Cast.Cst_Cnt = Bottle.Cst_Cnt) AND (Bottle.Btl_Cnt = Rpt_Data.Btl_Cnt) AND (Bottle.Btl_Cnt = Prodo_Bottle.Btl_Cnt) AND (Bottle.Btl_Cnt = Nuts.Btl_Cnt)
WHERE (((Cast.Cruise)=200501));
